using System.Text.Json.Serialization;

namespace PokeJuegos.Mobile.Models;

/// <summary>
/// <c>Resources/Raw/pokemon_list.json</c> (generated by <c>scripts/fetch_pokemon_list.py</c>): the PokeAPI
/// <c>/pokemon?limit=386</c> list response. Light on purpose; the details come from <see cref="Pokemon"/>.
/// </summary>
public sealed record PokemonListResponse(int Count, string? Next, string? Previous, IReadOnlyList<PokemonSummary> Results);

/// <param name="Url">PokeAPI detail URL, <c>https://pokeapi.co/api/v2/pokemon/25/</c>; the id is its last segment.</param>
public sealed record PokemonSummary(string Name, string Url)
{
	/// <summary>
	/// National dex number. The list only has name and URL, so it comes from the URL's last segment
	/// (<c>…/pokemon/25/</c>), the same way PokeAPI clients do it.
	/// </summary>
	/// <exception cref="FormatException">The URL doesn't end in a number.</exception>
	[JsonIgnore]
	public int Id => int.Parse(Url.TrimEnd('/').Split('/')[^1], System.Globalization.CultureInfo.InvariantCulture);
}

/// <summary>
/// One entry of <c>Resources/Raw/pokemon_details.json</c> (generated by <c>scripts/fetch_pokemon_details.py</c>),
/// in the same shape as the PokeAPI <c>/pokemon/{name}</c> response, trimmed down.
/// </summary>
/// <param name="Weight">In hectograms, as PokeAPI returns it.</param>
/// <param name="Height">In decimeters, as PokeAPI returns it.</param>
public sealed record Pokemon(
	int Id,
	string Name,
	int Generation,
	int Weight,
	int Height,
	IReadOnlyList<PokemonTypeSlot> Types,
	PokemonSprites Sprites);

public sealed record PokemonTypeSlot(int Slot, NamedResource Type);

public sealed record NamedResource(string Name, string Url);

public sealed record PokemonSprites(PokemonOtherSprites Other);

public sealed record PokemonOtherSprites(
	[property: JsonPropertyName("official-artwork")] OfficialArtwork OfficialArtwork);

/// <param name="FrontDefault">Bundled MAUI image name (<c>pokemon_25.webp</c>), rewritten by <c>fetch_pokemon_sprites.py</c>.</param>
/// <param name="FrontShiny">Remote URL; not bundled.</param>
public sealed record OfficialArtwork(
	[property: JsonPropertyName("front_default")] string? FrontDefault,
	[property: JsonPropertyName("front_shiny")] string? FrontShiny);

/// <summary>
/// Source-generated JSON metadata: no reflection at runtime, so trimming in the Release APK can't break it.
/// </summary>
[JsonSourceGenerationOptions(PropertyNamingPolicy = JsonKnownNamingPolicy.CamelCase)]
[JsonSerializable(typeof(PokemonListResponse))]
[JsonSerializable(typeof(List<Pokemon>))]
internal sealed partial class PokemonJsonContext : JsonSerializerContext;
